package com.vex.videoai.data
import org.json.JSONArray
import org.json.JSONObject
import java.util.UUID
data class SceneLayer(val id:String=UUID.randomUUID().toString(),val name:String,val kind:String="object",val x:Float=.5f,val y:Float=.5f,val scale:Float=1f,val visible:Boolean=true)
data class VideoScene(val id:String=UUID.randomUUID().toString(),val title:String,val durationSeconds:Int=6,val narration:String="",val dialogue:String="",val visualDescription:String="",val cameraMovement:String="Static",val transition:String="Cut",val layers:List<SceneLayer> = emptyList())
data class VideoProject(val id:String=UUID.randomUUID().toString(),val title:String,val idea:String,val category:String,val durationSeconds:Int,val aspectRatio:String,val visualStyle:String,val createdAt:Long=System.currentTimeMillis(),val scenes:List<VideoScene> = emptyList()) {
 fun toJson()=JSONObject().apply { put("id",id);put("title",title);put("idea",idea);put("category",category);put("durationSeconds",durationSeconds);put("aspectRatio",aspectRatio);put("visualStyle",visualStyle);put("createdAt",createdAt);put("scenes",JSONArray().apply { scenes.forEach { put(it.toJson()) } }) }
 companion object { fun fromJson(j:JSONObject):VideoProject { val a=j.optJSONArray("scenes")?:JSONArray();return VideoProject(j.optString("id",UUID.randomUUID().toString()),j.optString("title","Untitled project"),j.optString("idea"),j.optString("category","story"),j.optInt("durationSeconds",45),j.optString("aspectRatio","9:16"),j.optString("visualStyle","Cinematic"),j.optLong("createdAt",System.currentTimeMillis()),(0 until a.length()).mapNotNull { a.optJSONObject(it)?.let(::sceneFromJson) }) } }
}
private fun VideoScene.toJson()=JSONObject().apply { put("id",id);put("title",title);put("durationSeconds",durationSeconds);put("narration",narration);put("dialogue",dialogue);put("visualDescription",visualDescription);put("cameraMovement",cameraMovement);put("transition",transition);put("layers",JSONArray().apply { layers.forEach { l->put(JSONObject().apply { put("id",l.id);put("name",l.name);put("kind",l.kind);put("x",l.x.toDouble());put("y",l.y.toDouble());put("scale",l.scale.toDouble());put("visible",l.visible) }) } }) }
private fun sceneFromJson(j:JSONObject):VideoScene { val a=j.optJSONArray("layers")?:JSONArray();val layers=(0 until a.length()).mapNotNull { a.optJSONObject(it)?.let { l->SceneLayer(l.optString("id",UUID.randomUUID().toString()),l.optString("name","Layer"),l.optString("kind","object"),l.optDouble("x",.5).toFloat(),l.optDouble("y",.5).toFloat(),l.optDouble("scale",1.0).toFloat(),l.optBoolean("visible",true)) } };return VideoScene(j.optString("id",UUID.randomUUID().toString()),j.optString("title","Scene"),j.optInt("durationSeconds",6).coerceIn(1,120),j.optString("narration"),j.optString("dialogue"),j.optString("visualDescription"),j.optString("cameraMovement","Static"),j.optString("transition","Cut"),layers) }
